void loop() {
  bool changed = false;
  for(int row = 0; row < NUMBER_OF_SEND_PINS; ++row) {
    int sendPin = sendPins[row];
    digitalWrite(sendPin, HIGH);
    for(int col = 0; col < NUMBER_OF_RECEIVE_PINS; ++col) {
      int receivePin = receivePins[col];
      int value = digitalRead(receivePin);
      if(value == HIGH) {
        if(!values[row][col]) {
          changed = true;
          values[row][col] = 1;
        }
      }
      else {
        if(values[row][col]) {
          values[row][col] = 0;
          changed = true;
        }
      }
    }
